select *
from t_order_info


    and pay_status = #{payStatus}


    and order_status = #{orderStatus}


    and fulfillment_status = #{fulfillmentStatus}


    and order_no like #{orderNoLike}


    and user_id = #{userId}


    and create_time >= #{startTime}


    and create_time <= #{endTime}


order by create_time desc

select *
from t_order_info
where id = (
select id
from (
select id
from t_order_info
where product_id = #{productId}
and payment_type = #{paymentType}
and legacy_status = #{orderStatus}


    and payment_app_id = #{paymentAppId}


    and payment_app_id is null


order by create_time desc, id desc
) latest_order
where rownum <= 1
)

mapper.update:
update t_order_info
set refund_frozen_amount = refund_frozen_amount + #{amount}, update_time = CURRENT_TIMESTAMP
where order_no = #{orderNo}
and paid_amount - refunded_amount - refund_frozen_amount >= #{amount}

update t_order_info
set refund_frozen_amount = refund_frozen_amount - #{amount}, update_time = CURRENT_TIMESTAMP
where order_no = #{orderNo}
and refund_frozen_amount >= #{amount}

update t_order_info
set refund_frozen_amount = refund_frozen_amount - #{amount},
refunded_amount = refunded_amount + #{amount},
update_time = CURRENT_TIMESTAMP
where order_no = #{orderNo}
and refund_frozen_amount >= #{amount}
